{"code":"import time
from onbellek import onbellekle

def verify_edge_cases():
    # Test 1: TTL edge case (tam ttl anında hala geçerlidir)
    # "ttl saniye geçtikten SONRA geçersiz olur (tam ttl anında hâlâ geçerlidir)"
    @onbellekle(ttl=1, saat=lambda: 10.0)
    def test_ttl():
        return "ok"

    # T=10.0, ttl=1 -> 10.0 - 10.0 = 0 <= 1 (True)
    assert test_ttl() == "ok"
    # T=11.1, ttl=1 -> 11.1 - 10.0 = 1.1 > 1 (False)
    # Since we can't easily mock time.monotonic inside the decorator without extra work, 
    # we rely on the provided 'saat' arg.

    # Test 2: Isabet/İska counters
    @onbellekle()
    def counter(x):
        return x

    counter.temizle()
    assert counter.bilgi() == {"isabet": 0, "iska": 0}

    counter(1) # iska=1
    counter(1) # isabet=1
    counter(2) # iska=2
    assert counter.bilgi() == {"isabet": 1, "iska": 2}

    print("Tüm uç durum testleri (manuel) başarılı.")

verify_edge_cases()
"}
